var SEQ=1;
function addCounter(list, name){ name=(name||'').trim(); if(!name) return list; return list.concat([{id:SEQ++,name:name,count:0}]); }
function inc(list, id, n){ n=n||1; return list.map(function(c){ return c.id===id?{id:c.id,name:c.name,count:c.count+n}:c; }); }
function dec(list, id, n){ n=n||1; return list.map(function(c){ return c.id===id?{id:c.id,name:c.name,count:Math.max(0,c.count-n)}:c; }); }
function remove(list, id){ return list.filter(function(c){ return c.id!==id; }); }
function reset(list, id){ return list.map(function(c){ return c.id===id?{id:c.id,name:c.name,count:0}:c; }); }
function total(list){ return list.reduce(function(s,c){return s+c.count;},0); }
var EXPORTS={addCounter:addCounter,inc:inc,dec:dec,remove:remove,reset:reset,total:total};


